}

export default function FilterBar(props: FilterBarProps) {
 const {
 resource, priority, status, dateFrom, dateTo,
 onResourceChange, onPriorityChange, onStatusChange,
 onDateFromChange, onDateToChange, onApply,
 } = props;

 return (
 <div className="planner-filters">
 <div className="planner-filter-group">
 <label className="planner-filter-label">Resource</label>
 <input
 className="planner-filter-input"
 type="text"
 placeholder="Resource name"
 value={resource}
 onChange={(e) => onResourceChange(e.target.value)}
 />
 </div>

 <div className="planner-filter-group">
 <label className="planner-filter-label">Priority</label>
 <select className="planner-filter-select" value={priority} onChange={(e) => onPriorityChange(e.target.value)}>
 <option value="">All</option>
 <option value="critical">Critical</option>
 <option value="high">High</option>
 <option value="medium">Medium</option>
 <option value="low">Low</option>
 </select>
 </div>

 <div className="planner-filter-group">
 <label className="planner-filter-label">Status</label>
 <select className="planner-filter-select" value={status} onChange={(e) => onStatusChange(e.target.value)}>
 <option value="">All</option>
 <option value="draft">Draft</option>
 <option value="scheduled">Scheduled</option>
 <option value="confirmed">Confirmed</option>
 <option value="in_progress">In Progress</option>
 <option value="completed">Completed</option>
 <option value="cancelled">Cancelled</option>
 </select>
 </div>

 <div className="planner-filter-group">
 <label className="planner-filter-label">Date From</label>
 <input className="planner-filter-input" type="date" value={dateFrom} onChange={(e) => onDateFromChange(e.target.value)} />
 </div>

 <div className="planner-filter-group">
 <label className="planner-filter-label">Date To</label>
 <input className="planner-filter-input" type="date" value={dateTo} onChange={(e) => onDateToChange(e.target.value)} />
 </div>

 <div className="planner-filter-btn">
 <Button label="Apply Filters" variant="primary" onClick={onApply} />
 </div>
 </div>
 );
}
","import React, { useState } from "react";
import { Button } from "@servicenow/react-components/Button";

interface CreateSchedulePanelProps {
 onScheduleCreated: () => void;
}

export default function CreateSchedulePanel({ onScheduleCreated }: CreateSchedulePanelProps) {
 const [expanded, setExpanded] = useState(false);
 const [poSysId, setPoSysId] = useState("");
 const [submitting, setSubmitting] = useState(false);
 const [message, setMessage] = useState<{ type: "success" | "error"; text: string } | null>(null);

 const handleSubmit = async () => {
 if (!poSysId.trim()) {
 setMessage({ type: "error", text: "Please enter a Production Order sys_id" });
 return;
 }
 setSubmitting(true);
 setMessage(null);
 try {
 const res = await fetch("/api/x_2056099_indust_0/operator_api/create-schedule", {
 method: "POST",
 headers: {
 "Content-Type": "application/json",
 "X-UserToken": (window as any).g_ck || "",
 },
 body: JSON.stringify({ production_order_id: poSysId.trim() }),
 });
 const json = await res.json();
 const result = json.result || {};
 if (result.success) {
 setMessage({ type: "success", text: result.message || "Schedule created successfully" });
 setPoSysId("");
 onScheduleCreated();
 } else {
 setMessage({ type: "error", text: result.error || "Failed to create schedule" });
 }
 } catch (e: any) {
 setMessage({ type: "error", text: e.message || "Network error" });
 } finally {
 setSubmitting(false);
 }
 };

 return (
 <div className="create-schedule-panel">
 <div className="create-schedule-toggle" onClick={() => setExpanded(!expanded)} role="button" tabIndex={0} onKeyDown={(e) => e.key === "Enter" && setExpanded(!expanded)}>
 <span className="create-schedule-toggle-icon">{expanded ? "▼" : "▶"}</span>
 <span className="create-schedule-toggle-text">Create Schedule</span>
 </div>
 {expanded && (
 <div className="create-schedule-form">
 <div className="planner-filter-group" style={{ flex: 1 }}>
 <label className="planner-filter-label">Production Order sys_id</label>
 <input
 className="planner-filter-input"
 type="text"
 placeholder="Enter Production Order sys_id"
 value={poSysId}
 onChange={(e) => setPoSysId(e.target.value)}
 onKeyDown={(e) => e.key === "Enter" && handleSubmit()}
 />
 </div>
 <div className="planner-filter-btn">
 <Button variant="primary" onClick={handleSubmit} disabled={submitting}>
 {submitting ? "Scheduling..." : "Create Draft Schedule"}
 </Button>
 </div>
 {message && (
 <div className={`create-schedule-msg ${message.type === "success" ? "create-schedule-success" : "create-schedule-error"}`}>
 {message.text}
 </div>
 )}
 </div>
 )}
 </div>
 );
}
