","import React, { useState, useCallback } from "react";
import "./styles.css";
import FilterBar from "./components/FilterBar";
import CreateSchedulePanel from "./components/CreateSchedulePanel";
import ConfirmSchedulePanel from "./components/ConfirmSchedulePanel";
import { NowRecordListConnected } from "@servicenow/react-components/NowRecordListConnected";

function buildQuery(
 resource: string,
 priority: string,
 status: string,
 dateFrom: string,
 dateTo: string
): string {
 const parts: string[] = [];
 if (resource) parts.push(`production_resource=${resource}`);
 if (priority) parts.push(`priority=${priority}`);
 if (status) parts.push(`status=${status}`);
 if (dateFrom) parts.push(`planned_start>=${dateFrom}`);
 if (dateTo) parts.push(`planned_end<=${dateTo}`);
 parts.push("ORDERBYplanned_start");
 parts.push("ORDERBYpriority");
 return parts.join("^");
}

export default function App() {
 const [resource, setResource] = useState("");
 const [priority, setPriority] = useState("");
 const [status, setStatus] = useState("");
 const [dateFrom, setDateFrom] = useState("");
 const [dateTo, setDateTo] = useState("");
 const [appliedQuery, setAppliedQuery] = useState("");
 const [refreshKey, setRefreshKey] = useState(0);

 const handleApply = useCallback(() => {
 setAppliedQuery(buildQuery(resource, priority, status, dateFrom, dateTo));
 }, [resource, priority, status, dateFrom, dateTo]);

 const handleScheduleCreated = useCallback(() => {
 setRefreshKey(k => k + 1);
 handleApply();
 }, [handleApply]);

 return (
 <div className="planner-app">
 <div className="planner-header">
 <h1>Schedule Planner</h1>
 </div>
 <div className="planner-content">
 <FilterBar
 resource={resource}
 priority={priority}
 status={status}
 dateFrom={dateFrom}
 dateTo={dateTo}
 onResourceChange={setResource}
 onPriorityChange={setPriority}
 onStatusChange={setStatus}
 onDateFromChange={setDateFrom}
 onDateToChange={setDateTo}
 onApply={handleApply}
 />
 <CreateSchedulePanel onScheduleCreated={handleScheduleCreated} />
 <ConfirmSchedulePanel onScheduleConfirmed={handleScheduleCreated} />
 <NowRecordListConnected
 key={(appliedQuery || "default") + "_" + refreshKey}
 table="x_2056099_indust_0_prod_sched"
 query={appliedQuery}
 listTitle="Production Schedules"
 columns="number,production_order,priority,production_resource,planned_start,planned_end,planned_quantity,status"
 hideHeader={true}
 />
 </div>
 </div>
 );
}
